import { Component, inject, signal, computed, PLATFORM_ID, HostListener } from '@angular/core';
import { RouterLink, RouterLinkActive } from '@angular/router';
import { isPlatformBrowser } from '@angular/common';
import { ThemeService } from '../../../core/services/theme.service';
import { ScrollService } from '../../../core/services/scroll.service';
import { CursorService } from '../../../core/services/cursor.service';

@Component({
  selector: 'app-navbar',
  standalone: true,
  imports: [RouterLink, RouterLinkActive],
  templateUrl: './navbar.component.html',
  styleUrl: './navbar.component.scss'
})
export class NavbarComponent {
  private platformId = inject(PLATFORM_ID);
  theme = inject(ThemeService);
  scroll = inject(ScrollService);
  cursor = inject(CursorService);

  menuOpen = signal(false);
  scrolled = computed(() => this.scroll.scrollY() > 60);

  get scrollProgress(): string {
    if (!isPlatformBrowser(this.platformId)) return 'scaleX(0)';
    const max = document.body.scrollHeight - window.innerHeight;
    return `scaleX(${max > 0 ? this.scroll.scrollY() / max : 0})`;
  }

  navLinks = [
    { label: 'Work', path: '/portfolio' },
    { label: 'About', path: '/about' },
    { label: 'Services', path: '/services' },
    { label: 'Journal', path: '/blog' },
    { label: 'Contact', path: '/contact' },
  ];

  toggleMenu() {
    this.menuOpen.update(v => !v);
    if (isPlatformBrowser(this.platformId)) {
      document.body.style.overflow = this.menuOpen() ? 'hidden' : '';
    }
  }

  closeMenu() {
    this.menuOpen.set(false);
    if (isPlatformBrowser(this.platformId)) document.body.style.overflow = '';
  }

  @HostListener('window:keydown.escape')
  onEscape() { this.closeMenu(); }
}
